import Image from 'next/image';

/**
 * A guide's illustration: an SVG from public/images/blog/ (generated by
 * scripts/make_blog_images.py from the guide's own tables). `alt` carries what the
 * picture says; the same facts are in the guide's text and tables.
 */
export default function GuideFigure({ slug, alt, caption }: { slug: string; alt: string; caption: string }) {
  return (
    <figure className="cp-figure">
      <Image src={`/images/blog/${slug}.svg`} alt={alt} width={1200} height={630} unoptimized loading="lazy" />
      <figcaption>{caption}</figcaption>
    </figure>
  );
}
